// node app.js Ada  ->  Hello, Ada

// Single-line comment
/* Block comment
   spanning two lines */

// Statements end with a semicolon; it is optional but explicit is clearer
const total = 2 + 3;

// Braces group statements
{
  const inner = "only visible in this block";
  console.log(inner);
}

// Template literals interpolate expressions and keep line breaks
const user = "Ada";
console.log(`Hello, ${user}! 2 + 2 = ${2 + 2}`);

// Line breaks usually end a statement
const a = 1
const b = 2
console.log(a + b)   // 3

// A line starting with a bracket continues the previous expression,
// so leading semicolons protect against accidental calls
const sum = [1, 2, 3].reduce((acc, n) => acc + n, 0);
console.log(sum);    // 6

// undefined means "not assigned"; null is a deliberate empty value
let pending;
console.log(pending);            // undefined
console.log(null == undefined);  // true  (loose equality)
console.log(null === undefined); // false (strict equality)

// Numbers are IEEE-754 doubles, so some decimals are inexact
console.log(0.1 + 0.2);              // 0.30000000000000004
console.log(Number.isNaN(0 / 0));    // true
console.log(Number.isInteger(7.0));  // true
console.log(Number.MAX_SAFE_INTEGER); // 9007199254740991

// BigInt keeps large integers exact
console.log(9007199254740993n + 1n); // 9007199254740994n

// const is the default: the binding cannot be reassigned
const host = "localhost";

// let allows reassignment and is block scoped
let attempts = 0;
attempts += 1;
console.log(attempts); // 1

// var is function scoped and hoisted, so prefer let and const
if (true) {
  var leaked = "visible after the block";
  let scoped = "only inside the block";
}
console.log(leaked);
// console.log(scoped); // ReferenceError: scoped is not defined

// A let binding is unusable until its declaration executes
// console.log(level); // ReferenceError: Cannot access 'level' before initialization
let level = 1;

// const protects the binding, not the value behind it
const roles = ["admin"];
roles.push("editor");
console.log(roles);  // [ 'admin', 'editor' ]
// roles = [];       // TypeError: Assignment to constant variable.

// Destructuring swaps two values without a temporary
let left = "a";
let right = "b";
[left, right] = [right, left];
console.log(left, right); // b a

// Arithmetic and assignment shortcuts
console.log(7 % 3);   // 1
console.log(2 ** 8);  // 256
let score = 10;
score += 5;           // 15
score *= 2;           // 30

// === compares type and value; == coerces before comparing
console.log("5" === 5); // false
console.log("5" == 5);  // true

// Logical operators return an operand, not always a boolean
console.log(0 || "fallback");    // "fallback"
console.log("" && "never");      // ""
console.log(null ?? "default");  // "default"

const user = { profile: { city: "Recife" } };

// Optional chaining stops at the first null or undefined
console.log(user.profile?.city);  // "Recife"
console.log(user.account?.city);  // undefined

// Nullish assignment writes only when the target is null or undefined
const settings = { theme: null, zoom: 1 };
settings.theme ??= "dark";
settings.zoom ??= 2;
console.log(settings); // { theme: 'dark', zoom: 1 }

// Ternary chooses a value; spread copies properties
const label = settings.zoom > 1 ? "large" : "normal";
const merged = { ...settings, lang: "pt-BR" };
console.log(label, merged.lang); // large pt-BR

const status = 404;

if (status >= 200 && status < 300) {
  console.log("success");
} else if (status === 404) {
  console.log("not found");
} else {
  console.log("other");
}

switch (status) {
  case 200:
    console.log("ok");
    break;
  case 404:
    console.log("missing");
    break;
  default:
    console.log("unknown");
}

const numbers = [4, 8, 15, 16, 23, 42];

for (const n of numbers) {
  if (n % 2 !== 0) continue;  // skip odd values
  if (n > 20) break;          // stop after 20
  console.log(n);             // 4, 8, 16
}

// for...in walks property names; use it for objects, not array values
const config = { retries: 3, timeout: 500 };
for (const key in config) {
  console.log(key, config[key]); // retries 3, then timeout 500
}

let remaining = 3;
while (remaining > 0) {
  remaining -= 1;
}
console.log(remaining); // 0

// Declarations are hoisted and callable before their definition
console.log(add(2, 3)); // 5
function add(a, b) {
  return a + b;
}

// Arrow functions with an implicit return
const double = (n) => n * 2;
console.log(double(21)); // 42

// Default and rest parameters
function greet(name = "guest", ...titles) {
  return `${titles.join(" ")} ${name}`.trim();
}
console.log(greet("Ada", "Dr.")); // Dr. Ada

// Closures keep access to the scope where they were created
function makeCounter(start = 0) {
  let value = start;
  return {
    increment: () => ++value,
    current: () => value,
  };
}

const counter = makeCounter(10);
counter.increment();
counter.increment();
console.log(counter.current()); // 12

// Functions are values: pass them around and call them later
const apply = (fn, value) => fn(value);
console.log(apply((n) => n + 1, 5)); // 6

// Regular functions get their own this; arrows inherit it from the caller
const timer = {
  seconds: 0,
  start() {
    setTimeout(() => {
      this.seconds += 1;
    }, 1000);
  },
};
timer.start();

const scores = [72, 95, 48, 88];

// map transforms, filter keeps, reduce folds
const doubled = scores.map((n) => n * 2);
const passed = scores.filter((n) => n >= 60);
const total = scores.reduce((sum, n) => sum + n, 0);
console.log(doubled); // [ 144, 190, 96, 176 ]
console.log(passed);  // [ 72, 95, 88 ]
console.log(total);   // 303

// find returns the first match; at counts from the end
console.log(scores.find((n) => n < 60)); // 48
console.log(scores.at(-1));              // 88

const names = ["ada", "Grace", "linus"];

// sort mutates and compares as text by default, so pass a comparator
names.sort((a, b) => a.localeCompare(b));
console.log(names); // [ 'ada', 'Grace', 'linus' ]

// Numeric order needs subtraction
const values = [10, 9, 100];
values.sort((a, b) => a - b);
console.log(values); // [ 9, 10, 100 ]

// some, every and flat
console.log(values.some((n) => n > 50)); // true
console.log(values.every((n) => n > 5)); // true
console.log([[1, 2], [3, 4]].flat());    // [ 1, 2, 3, 4 ]

// Copy before adding so the original stays intact
const original = [1, 2, 3];
const copy = [...original, 4];
console.log(original, copy); // [ 1, 2, 3 ] [ 1, 2, 3, 4 ]

const user = { name: "Ada", age: 36 };

// Dot access for fixed keys, brackets for dynamic ones
console.log(user.name);   // "Ada"
console.log(user["age"]); // 36

// Shorthand properties, computed keys and methods
const key = "role";
const account = {
  user,
  [key]: "admin",
  greet() {
    return `Hi, ${this.user.name}`;
  },
};
console.log(account.greet()); // Hi, Ada
console.log(account.role);    // admin

const point = { x: 3, y: 7, z: 0 };

// Destructuring with rest collects the remaining keys
const { x, y, ...rest } = point;
console.log(x, y, rest); // 3 7 { z: 0 }

// Object helpers
console.log(Object.keys(point));    // [ 'x', 'y', 'z' ]
console.log(Object.values(point));  // [ 3, 7, 0 ]
console.log(Object.entries(point)); // [ [ 'x', 3 ], [ 'y', 7 ], [ 'z', 0 ] ]

// Copy with an override, leaving the source unchanged
const shifted = { ...point, x: 10 };
console.log(point.x, shifted.x); // 3 10

// Freeze blocks new changes in strict mode
const limits = Object.freeze({ max: 5 });
// limits.max = 9; // TypeError: Cannot assign to read only property
console.log(limits.max); // 5

const name = "Ada";

// Template literals interpolate values and keep formatting
const message = `Hello, ${name}.`;
console.log(message);              // Hello, Ada.
console.log(`2 + 3 = ${2 + 3}`);  // 2 + 3 = 5

// Trim, case and length
console.log("  spaced  ".trim()); // "spaced"
console.log("ada".toUpperCase()); // "ADA"
console.log("Ada".length);        // 3

const csv = "ana,bruno,carla";

// split and join convert between text and arrays
const people = csv.split(",");
console.log(people);            // [ 'ana', 'bruno', 'carla' ]
console.log(people.join(" | ")); // ana | bruno | carla

// Search and replace
console.log(csv.includes("bruno"));        // true
console.log(csv.startsWith("ana"));        // true
console.log(csv.replace("bruno", "bia"));  // ana,bia,carla
console.log("a-b-a".replaceAll("a", "x")); // x-b-x

// slice excludes the end index; padStart fixes the width
