console.log("hello".at(-1));       // "o"

class Counter {
  #count = 0; // private field, unreachable from outside

  constructor(start = 0) {
    this.#count = start;
  }

  increment(step = 1) {
    this.#count += step;
    return this;
  }

  get value() {
    return this.#count;
  }

  static zero() {
    return new Counter(0);
  }
}

const counter = Counter.zero().increment(2).increment(3);
console.log(counter.value); // 5
// console.log(counter.#count); // SyntaxError: private field outside the class

class Animal {
  constructor(name) {
    this.name = name;
  }

  get sound() {
    return "...";
  }

  speak() {
    return `${this.name} says ${this.sound}`;
  }
}

class Dog extends Animal {
  get sound() {
    return "woof";
  }

  speak() {
    return `${super.speak()}!`;
  }
}

const dog = new Dog("Toby");
console.log(dog.speak());           // Toby says woof!
console.log(dog instanceof Dog);    // true
console.log(dog instanceof Animal); // true

// math.js
export const PI = 3.14159;

export function area(radius) {
  return PI * radius ** 2;
}

export default function describe(radius) {
  return `circle of radius ${radius}`;
}

// app.js
import describe, { PI, area } from "./math.js";

console.log(PI);                 // 3.14159
console.log(area(2).toFixed(2)); // 12.57
console.log(describe(3));        // circle of radius 3

// A namespace import groups every named export
import * as math from "./math.js";
console.log(math.PI === PI); // true

// Dynamic import resolves at call time and returns a promise
const mod = await import("./math.js");
console.log(mod.area(1).toFixed(2)); // 3.14

// A promise settles once: fulfilled with a value or rejected with an error
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function loadUser(id) {
  await wait(500);
  if (id <= 0) throw new Error(`invalid id: ${id}`);
  return { id, name: "Ada" };
}

loadUser(7).then((user) => console.log(user.name));          // Ada
loadUser(0).catch((error) => console.log(error.message));    // invalid id: 0

async function fetchTitle(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`); // 404 for a missing page
  }
  return response.json();
}

try {
  const data = await fetchTitle("https://example.com/data.json");
  console.log(data.title);
} catch (error) {
  console.error(error.message);
}

// allSettled waits for every promise and reports each outcome
const tasks = [
  Promise.resolve("ok"),
  Promise.reject(new Error("boom")),
  Promise.resolve("fine"),
];

const results = await Promise.allSettled(tasks);
console.log(results[0]); // { status: 'fulfilled', value: 'ok' }
console.log(results[1]); // { status: 'rejected', reason: Error: boom }
console.log(results.map((r) => r.status)); // [ 'fulfilled', 'rejected', 'fulfilled' ]

