const user = { profile: null };

// TypeError: the property read happens on a null value
// console.log(user.profile.name);
// TypeError: Cannot read properties of null (reading 'name')

// Optional chaining plus a fallback keeps the read safe
console.log(user.profile?.name ?? "anonymous"); // anonymous

// Assigning to an undeclared name throws in strict mode,
// and ES modules are always strict
// total = 1; // ReferenceError: total is not defined
let total = 1;
console.log(total); // 1

// Losing this: a detached method forgets its receiver
const counter = {
  count: 5,
  read() {
    return this.count;
  },
};

const read = counter.read;
// read(); // TypeError: Cannot read properties of undefined (reading 'count')
console.log(counter.read());                 // 5
console.log(read.call(counter));             // 5
console.log(counter.read.call({ count: 9 })); // 9

// Decimal sums rarely compare equal, so use a tolerance
console.log(0.1 + 0.2 === 0.3);                // false
console.log(Math.abs(0.1 + 0.2 - 0.3) < 1e-9); // true

